files.content:
@use 'styles' as vz;

.wrapper {
  position: relative;
  width: 100%;
  overflow: auto;
  border-radius: vz.radius('md');

  @include vz.focus-ring;
}

.root {
  width: 100%;
  border-collapse: collapse;
  caption-side: bottom;
  font-size: vz.font-size('sm');
}

.row {
  border-bottom: 1px solid vz.color('border');
  transition: background-color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('muted', 0.5);
  }
}

.row[data-state='selected'] {
  background: vz.color('muted');
}

.footer .row {
  border-bottom: 0;
}

.body .row:last-child {
  border-bottom: 0;
}

.footer {
  border-top: 1px solid vz.color('border');
  background: vz.color('muted', 0.5);
  font-weight: 500;
}

.head {
  height: vz.space(12);
  padding-inline: vz.space(4);
  color: vz.color('muted-foreground');
  font-weight: 500;
  text-align: left;
  vertical-align: middle;

  &:has([role='checkbox']) {
    padding-inline-end: 0;
  }
}

.cell {
  padding: vz.space(4);
  vertical-align: middle;

  &:has([role='checkbox']) {
    padding-inline-end: 0;
  }
}

.caption {
  margin-top: vz.space(4);
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');
}
